 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Color 2 is a hub: it expands horizontally by two cells on each side,
    # with the side cells colored 5. Other markers extend their line through
    # the marker, in both directions, by the same distance as the 2 motif.
    pts = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                pts.setdefault(grid[r][c], []).append((r,c))
    if 2 not in pts:
        return out
    r,c = pts[2][0]
    for cc in (c-2,c-1,c+1,c+2):
        if 0 <= cc < w:
            out[r][cc] = 5
    # Extend each other colored singleton in its aligned cardinal/diagonal direction
    # away from the hub; distance is the coordinate separation from the hub.
    for color, positions in pts.items():
        if color == 2: continue
        for rr,cc in positions:
            dr,dc = rr-r,cc-c
            if dr == 0 and dc == 0: continue
            # Extend from marker outward, retaining marker color on endpoint copy,
            # and fill intervening cells with 5.
            steps = max(abs(dr), abs(dc))
            if dr == 0 or dc == 0 or abs(dr)==abs(dc):
                sr = 0 if dr==0 else (1 if dr>0 else -1)
                sc = 0 if dc==0 else (1 if dc>0 else -1)
                for k in range(1, steps+1):
                    y,x=rr+sr*k,cc+sc*k
                    if 0<=y<h and 0<=x<w:
                        out[y][x] = color if k==steps else 5
    return out

